/* Portfolio project graph.
 * Data comes from data/projects.js (generated by build_data.py).
 * Projects are coloured by portfolio section; theme hubs join projects that share a topic.
 */
(() => {
  const projects = window.PORTFOLIO_PROJECTS || [];
  if (!window.d3 || !projects.length) return;

  // ---------------------------------------------------------------------
  // 1. Themes: keyword rules applied to each project's title + tagline
  // ---------------------------------------------------------------------
  const THEME_RULES = {
    'Memory':            /memory|mind palace|temporal|chronotope|mirror|atlas|remember/i,
    'Generative AI':     /lora|diffusion|controlnet|generative|noise|gridphoto|gemma|fine-tun|persona|ai[- ]driven|npc/i,
    'Computer Vision':   /vision|caption|webcam|blip|face|yolo|visual|llava|semiotic|sorter/i,
    'Sound & Audio':     /sound|audio|acoustic|birdsong|reverb|bioacoustic/i,
    '3D & Spatial':      /3d|spatial|\bxr\b|\bvr\b|\bar\b|morpholog|architecture|pontoon|modelling/i,
    'Accessibility':     /accessib|disab|blind|adhd|prosthe|assistive|special children|patient|inclusive/i,
    'Interactive Art':   /interactive|kinetic|installation|puppet|lighting|couture|compute\.\s*(art|play)|arduino/i,
    'Parametric Design': /parametric|algorithmic|node param|bio-morph|biomimicry|generative 3d/i,
    'Speculative':       /speculative|mythos|fictional|sci-fi|xeno|character|alter-ego|concept|skims/i,
    'Tools & Apps':      /studio|\bapp\b|tracker|quiz|reader|generator|filing|sorter|stopwatch|rsvp|dataset|gridphoto/i,
    'Industrial Design': /industrial|sketch|equipment|furniture|kara|artemis|budding|prosthe|flood|water|couture/i,
    'Research':          /research|evaluation|govt|analysis|semiotic|study|quiz/i
  };

  const sections = [...new Set(projects.map(p => p.section))];
  const palette = ['#c85f42', '#4f81ce', '#2f8579', '#9070c4', '#b8791f', '#c04a74'];
  const sectionColor = new Map(sections.map((s, i) => [s, palette[i % palette.length]]));

  const nodes = [];
  const links = [];
  const byId = new Map();

  projects.forEach((p, i) => {
    const text = `${p.title} ${p.tagline}`;
    const themes = Object.keys(THEME_RULES).filter(t => THEME_RULES[t].test(text));
    const n = {
      id: `p:${i}`, type: 'project', label: p.title, data: p, themes,
      color: sectionColor.get(p.section), section: p.section
    };
    nodes.push(n); byId.set(n.id, n);
  });

  Object.keys(THEME_RULES).forEach(t => {
    const members = nodes.filter(n => n.type === 'project' && n.themes.includes(t));
    if (members.length < 2) return;
    const tn = { id: `t:${t}`, type: 'theme', label: t, color: 'var(--muted)', members };
    nodes.push(tn); byId.set(tn.id, tn);
    members.forEach(m => links.push({ source: m.id, target: tn.id }));
  });

  // Projects that matched only dropped themes keep working; recompute their live theme list.
  const themeIds = new Set(nodes.filter(n => n.type === 'theme').map(n => n.label));
  nodes.filter(n => n.type === 'project').forEach(n => { n.themes = n.themes.filter(t => themeIds.has(t)); });

  const neighbors = new Map(nodes.map(n => [n.id, new Set()]));
  links.forEach(l => { neighbors.get(l.source).add(l.target); neighbors.get(l.target).add(l.source); });

  // ---------------------------------------------------------------------
  // 2. Sizing & layout
  // ---------------------------------------------------------------------
  const maxTheme = d3.max(nodes.filter(n => n.type === 'theme'), n => n.members.length) || 1;
  const themeR = d3.scaleSqrt().domain([2, Math.max(3, maxTheme)]).range([13, 26]);
  nodes.forEach(n => {
    n.r = n.type === 'theme' ? themeR(n.members.length) : 6 + Math.min(n.themes.length, 4) * 1.6;
    n.labelWidth = n.label.length * 6.3;
  });

  // Section anchors on a ring so each section forms a neighbourhood.
  const ring = 150 + sections.length * 35;
  const anchors = new Map(sections.map((s, i) => {
    const a = (i / sections.length) * Math.PI * 2 - Math.PI / 2;
    return [s, { x: Math.cos(a) * ring, y: Math.sin(a) * ring * 0.75 }];
  }));

  nodes.forEach((n, i) => {
    const a = i * 2.399963;
    const base = n.type === 'project' ? anchors.get(n.section) : { x: 0, y: 0 };
    n.x = base.x + Math.cos(a) * (20 + i * 2);
    n.y = base.y + Math.sin(a) * (20 + i * 2);
  });

  const simulation = d3.forceSimulation(nodes)
    .force('link', d3.forceLink(links).id(d => d.id).distance(l => 60 + l.target.r).strength(0.28))
    .force('charge', d3.forceManyBody().strength(n => (n.type === 'theme' ? -520 : -150)).distanceMax(700))
    .force('x', d3.forceX(n => (n.type === 'project' ? anchors.get(n.section).x : 0)).strength(n => (n.type === 'project' ? 0.12 : 0.03)))
    .force('y', d3.forceY(n => (n.type === 'project' ? anchors.get(n.section).y : 0)).strength(n => (n.type === 'project' ? 0.14 : 0.04)))
    .force('collide', d3.forceCollide(n => Math.max(n.r + 8, Math.min(n.labelWidth / 2 + 4, 60))).strength(0.9).iterations(2))
    .stop();
  for (let i = 0; i < 450; i++) simulation.tick();

  // ---------------------------------------------------------------------
  // 3. DOM
  // ---------------------------------------------------------------------
  const $ = id => document.getElementById(id);
  const root = $('project-graph'), canvas = $('pg-canvas'), stage = $('pg-stage');
  const tooltip = $('pg-tooltip'), hint = $('pg-hint'), panel = $('pg-panel');
  const searchInput = $('pg-search-input'), suggestions = $('pg-suggestions'), legendEl = $('pg-legend');
  const themesToggle = $('pg-toggle-themes');

  const coarse = matchMedia('(pointer: coarse)').matches;
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const ms = v => (reduced ? 0 : v);
  const isNarrow = () => matchMedia('(max-width: 720px)').matches;

  const projectNodes = nodes.filter(n => n.type === 'project');
  $('pg-stats').textContent =
    `${projectNodes.length} projects · ${themeIds.size} themes · ${sections.length} sections`;
  $('pg-help').textContent = coarse
    ? 'Tap a node for details · Drag to move · Pinch to zoom'
    : 'Click a node for details · Drag to pan · Scroll to zoom · Esc to close';

  // dark / light
  const saved = localStorage.getItem('pg-theme');
  if (saved) document.documentElement.dataset.theme = saved;
  else if (matchMedia('(prefers-color-scheme: dark)').matches) document.documentElement.dataset.theme = 'dark';
  $('pg-theme-btn').addEventListener('click', () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('pg-theme', next);
  });

  const svg = d3.select(canvas).append('svg')
    .attr('role', 'img')
    .attr('aria-label', `Graph of ${projectNodes.length} portfolio projects and the themes they share`);
  const viewport = svg.append('g');

  const linkSel = viewport.append('g').attr('aria-hidden', 'true')
    .selectAll('line').data(links).join('line')
    .attr('class', 'pg-link').attr('stroke-width', 1.2);

  const nodeSel = viewport.append('g').selectAll('g')
    .data([...nodes].sort((a, b) => (a.type === 'theme') - (b.type === 'theme')))
    .join('g')
    .attr('class', n => `pg-node ${n.type === 'theme' ? 'is-theme' : 'is-project'}`)
    .attr('tabindex', 0).attr('role', 'button')
    .attr('aria-label', n => (n.type === 'theme' ? `Theme ${n.label}: ${n.members.length} projects` : `${n.label}, ${n.section}`))
    .style('--node-color', n => n.color);

  nodeSel.append('circle').attr('class', 'pg-node-halo').attr('r', n => n.r + 7);
  nodeSel.append('circle').attr('class', 'pg-node-dot').attr('r', n => n.r);
  nodeSel.filter(n => n.type === 'theme').append('circle').attr('class', 'pg-node-core').attr('r', n => n.r * 0.32);
  nodeSel.append('text').attr('class', 'pg-node-label').attr('text-anchor', 'middle')
    .attr('dy', n => n.r + 14).text(n => n.label);

  function render() {
    linkSel.attr('x1', l => l.source.x).attr('y1', l => l.source.y).attr('x2', l => l.target.x).attr('y2', l => l.target.y);
    nodeSel.attr('transform', n => `translate(${n.x},${n.y})`);
  }
  render();
  simulation.on('tick', render);

  if (!reduced) {
    nodeSel.style('opacity', 0).transition().delay((n, i) => 100 + i * 12).duration(380).style('opacity', 1);
    linkSel.style('opacity', 0).transition().delay(300).duration(600).style('opacity', null);
  }

  // ---------------------------------------------------------------------
  // 4. Zoom & pan
  // ---------------------------------------------------------------------
  let userMoved = false, hintTimer = null;
  const flash = text => {
    hint.textContent = text; hint.classList.add('is-visible');
    clearTimeout(hintTimer); hintTimer = setTimeout(() => hint.classList.remove('is-visible'), 1600);
  };

  const zoom = d3.zoom().scaleExtent([0.2, 4])
    .filter(e => (e.type === 'wheel' ? true : !e.button))
    .on('start', e => { if (e.sourceEvent) userMoved = true; })
    .on('zoom', e => {
      viewport.attr('transform', e.transform);
      canvas.classList.toggle('is-far', e.transform.k < 0.85);
      hideTooltip();
    });
  svg.call(zoom).on('dblclick.zoom', null);

  const visible = () => nodes.filter(n => themesToggle.checked || n.type !== 'theme');
  const stageSize = () => ({ w: stage.clientWidth, h: stage.clientHeight });
  function area() {
    const { w, h } = stageSize();
    if (panel.hidden) return { w, h };
    return isNarrow() ? { w, h: h - panel.offsetHeight - 8 } : { w: w - panel.offsetWidth - 14, h };
  }

  function fitTransform(subset = visible(), pad = isNarrow() ? 16 : 56) {
    const a = area();
    const [x0, x1] = d3.extent(subset.flatMap(n => [n.x - Math.max(n.r, n.labelWidth / 2), n.x + Math.max(n.r, n.labelWidth / 2)]));
    const [y0, y1] = d3.extent(subset.flatMap(n => [n.y - n.r, n.y + n.r + 20]));
    const bw = Math.max(1, x1 - x0), bh = Math.max(1, y1 - y0);
    const k = Math.max(0.2, Math.min(subset.length === 1 ? 1.6 : 1.5, (a.w - pad * 2) / bw, (a.h - pad * 2) / bh));
    return d3.zoomIdentity.translate(a.w / 2 - k * (x0 + bw / 2), a.h / 2 - k * (y0 + bh / 2)).scale(k);
  }
  function fitView(animate = true, subset) {
    const t = fitTransform(subset);
    (animate ? svg.transition().duration(ms(600)).ease(d3.easeCubicInOut) : svg).call(zoom.transform, t);
  }
  function isInView(n) {
    const [sx, sy] = d3.zoomTransform(svg.node()).apply([n.x, n.y]);
    const a = area(), m = 24;
    return sx > m && sx < a.w - m && sy > m && sy < a.h - m;
  }

  $('pg-zoom-in').addEventListener('click', () => { userMoved = true; svg.transition().duration(ms(250)).call(zoom.scaleBy, 1.35); });
  $('pg-zoom-out').addEventListener('click', () => { userMoved = true; svg.transition().duration(ms(250)).call(zoom.scaleBy, 1 / 1.35); });
  $('pg-zoom-fit').addEventListener('click', () => { userMoved = false; fitView(true); });

  fitView(false);
  let last = stageSize();
  new ResizeObserver(() => {
    const s = stageSize();
    if (s.w === last.w && s.h === last.h) return;
    last = s;
    if (!userMoved) fitView(false);
  }).observe(stage);

  // Hide / show theme hubs
  function applyThemeVisibility() {
    const on = themesToggle.checked;
    nodeSel.classed('is-hidden', n => n.type === 'theme' && !on);
    linkSel.classed('is-hidden', () => !on);
    userMoved = false;
    if (!on && state.selected && state.selected.type === 'theme') select(null);
    fitView(true);
  }
  themesToggle.addEventListener('change', applyThemeVisibility);

  // ---------------------------------------------------------------------
  // 5. Highlight state
  // ---------------------------------------------------------------------
  const state = { hovered: null, selected: null, section: null, query: '' };
  const matches = n => state.query && (`${n.label} ${n.data ? n.data.tagline : ''}`).toLowerCase().includes(state.query);

  function applyState() {
    const focus = state.hovered || state.selected;
    const near = focus ? neighbors.get(focus.id) : null;
    const anyMatch = state.query && nodes.some(matches);

    nodeSel
      .classed('is-focus', n => n === focus || n === state.selected)
      .classed('is-neighbor', n => !!near && near.has(n.id))
      .classed('is-match', n => !focus && matches(n))
      .classed('is-dim', n => {
        if (focus) return n !== focus && n !== state.selected && !near.has(n.id);
        if (anyMatch) return !matches(n);
        if (state.section) return n.type === 'project' ? n.section !== state.section : !n.members.some(m => m.section === state.section);
        return false;
      });

    linkSel
      .classed('is-active', l => !!focus && (l.source === focus || l.target === focus))
      .classed('is-dim', l => {
        if (focus) return l.source !== focus && l.target !== focus;
        if (anyMatch) return true;
        if (state.section) return l.source.section !== state.section;
        return false;
      })
      .style('--link-color', l => {
        const p = l.source.type === 'project' ? l.source : l.target;
        return p.color;
      });
  }

  // ---------------------------------------------------------------------
  // 6. Tooltip
  // ---------------------------------------------------------------------
  function showTooltip(n) {
    const [sx, sy] = d3.zoomTransform(svg.node()).apply([n.x, n.y - n.r]);
    tooltip.innerHTML = '';
    const name = document.createElement('strong'); name.textContent = n.label;
    const meta = document.createElement('span');
    meta.textContent = n.type === 'theme' ? `${n.members.length} projects` : (n.data.year || n.section);
    tooltip.append(name, meta);
    tooltip.style.left = `${sx}px`; tooltip.style.top = `${sy}px`;
    tooltip.classList.add('is-visible');
  }
  function hideTooltip() { tooltip.classList.remove('is-visible'); }

  // ---------------------------------------------------------------------
  // 7. Panel & selection
  // ---------------------------------------------------------------------
  const el = {
    cover: $('pg-panel-cover'), title: $('pg-panel-title'), meta: $('pg-panel-meta'), desc: $('pg-panel-desc'),
    open: $('pg-panel-open'), themes: $('pg-panel-themes'), themesLabel: $('pg-themes-label'),
    projects: $('pg-panel-projects'), projectsLabel: $('pg-projects-label')
  };

  function chip(n, { count, pressed, onClick } = {}) {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'pg-chip';
    b.style.setProperty('--node-color', n.color);
    if (pressed !== undefined) b.setAttribute('aria-pressed', String(pressed));
    const dot = document.createElement('span');
    dot.className = `pg-chip-dot${n.type === 'theme' ? ' is-ring' : ''}`;
    const label = document.createElement('span'); label.textContent = n.label;
    b.append(dot, label);
    if (count !== undefined) {
      const c = document.createElement('span'); c.className = 'pg-chip-count'; c.textContent = count; b.append(c);
    }
    b.addEventListener('click', onClick);
    return b;
  }

  function listItem(n) {
    const li = document.createElement('li');
    const b = document.createElement('button'); b.type = 'button';
    const t = document.createElement('span'); t.className = 'pg-list-title';
    const dot = document.createElement('span'); dot.className = 'pg-chip-dot'; dot.style.setProperty('--node-color', n.color);
    const name = document.createElement('span'); name.textContent = n.label;
    t.append(dot, name);
    const sub = document.createElement('span'); sub.className = 'pg-list-sub';
    sub.textContent = [n.data.year, n.data.tagline].filter(Boolean).join(' · ');
    b.append(t, sub);
    b.addEventListener('click', () => select(n, { recenter: true }));
    li.append(b);
    return li;
  }

  function renderPanel(n) {
    panel.style.setProperty('--node-color', n.type === 'theme' ? 'var(--accent)' : n.color);
    el.title.textContent = n.label;
    el.projects.innerHTML = ''; el.themes.innerHTML = '';

    if (n.type === 'project') {
      const p = n.data;
      el.cover.hidden = !p.image;
      el.cover.style.backgroundImage = p.image ? `url("${p.image}")` : '';
      el.meta.textContent = [p.year, p.section].filter(Boolean).join(' · ');
      el.desc.textContent = p.tagline;
      el.open.href = p.url; el.open.hidden = false;
      el.themesLabel.hidden = !n.themes.length;
      n.themes.forEach(t => el.themes.append(chip(byId.get(`t:${t}`), { onClick: () => select(byId.get(`t:${t}`), { recenter: true }) })));
      // Other projects that share at least one theme, most shared first.
      const rel = projectNodes
        .filter(o => o !== n).map(o => ({ o, w: o.themes.filter(t => n.themes.includes(t)).length }))
        .filter(x => x.w > 0).sort((a, b) => b.w - a.w || a.o.label.localeCompare(b.o.label)).slice(0, 8);
      el.projectsLabel.hidden = !rel.length;
      el.projectsLabel.textContent = 'Related projects';
      rel.forEach(({ o }) => el.projects.append(listItem(o)));
    } else {
      el.cover.hidden = true;
      el.meta.textContent = `Theme · ${n.members.length} projects`;
      el.desc.textContent = '';
      el.open.hidden = true;
      el.themesLabel.hidden = true;
      el.projectsLabel.hidden = false; el.projectsLabel.textContent = 'Projects';
      [...n.members].sort((a, b) => (b.data.year || '').localeCompare(a.data.year || '') || a.label.localeCompare(b.label))
        .forEach(m => el.projects.append(listItem(m)));
    }
    panel.querySelector('.pg-panel-body').scrollTop = 0;
  }

  function updateHash(n) {
    const url = new URL(location.href);
    url.hash = n ? `node=${encodeURIComponent(n.id)}` : '';
    history.replaceState(null, '', n ? url.href : url.pathname + url.search);
  }

  function select(n, { recenter = false } = {}) {
    state.selected = n; state.section = null; syncLegend();
    if (!n) {
      panel.hidden = true; root.classList.remove('has-panel'); updateHash(null); applyState(); return;
    }
    renderPanel(n);
    panel.hidden = false; root.classList.add('has-panel'); updateHash(n); applyState();
    const hood = [n, ...[...neighbors.get(n.id)].map(id => byId.get(id))].filter(x => themesToggle.checked || x.type !== 'theme');
    // A theme's neighbours are its projects; a project's are its themes. Include both ends for context.
    if (n.type === 'project') n.themes.forEach(t => byId.get(`t:${t}`).members.forEach(m => hood.push(m)));
    if (recenter || !hood.every(isInView)) { userMoved = true; fitView(true, hood.slice(0, 80)); }
  }
  $('pg-panel-close').addEventListener('click', () => select(null));

  // ---------------------------------------------------------------------
  // 8. Node interaction
  // ---------------------------------------------------------------------
  let dragging = false;
  nodeSel
    .on('pointerenter', (e, n) => { if (dragging || e.pointerType === 'touch') return; state.hovered = n; applyState(); showTooltip(n); })
    .on('pointerleave', () => { if (dragging) return; state.hovered = null; applyState(); hideTooltip(); })
    .on('click', (e, n) => { e.stopPropagation(); hideTooltip(); select(state.selected === n ? null : n); })
    .on('focus', (e, n) => { state.hovered = n; applyState(); showTooltip(n); })
    .on('blur', () => { state.hovered = null; applyState(); hideTooltip(); })
    .on('keydown', (e, n) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(n); } });

  nodeSel.call(d3.drag().clickDistance(4)
    .on('start', (e, n) => { dragging = true; hideTooltip(); if (!e.active) simulation.alphaTarget(0.12).restart(); n.fx = n.x; n.fy = n.y; })
    .on('drag', (e, n) => { n.fx = e.x; n.fy = e.y; })
    .on('end', (e, n) => { dragging = false; if (!e.active) simulation.alphaTarget(0); n.fx = null; n.fy = null; }));

  svg.on('click', e => { if (!e.target.closest('.pg-node')) select(null); });

  // ---------------------------------------------------------------------
  // 9. Legend (sections)
  // ---------------------------------------------------------------------
  const legendChips = sections.map(s => {
    const members = projectNodes.filter(n => n.section === s);
    const c = chip({ label: s, color: sectionColor.get(s), type: 'project' }, {
      count: members.length, pressed: false,
      onClick: () => {
        const next = state.section === s ? null : s;
        if (state.selected) select(null);
        state.section = next; syncLegend(); applyState();
        if (next) { userMoved = true; fitView(true, members); }
      }
    });
    c.addEventListener('pointerenter', () => {
      if (state.selected || state.section) return;
      state.section = s; applyState(); state.section = null;
    });
    c.addEventListener('pointerleave', () => applyState());
    legendEl.append(c);
    return { s, c };
  });
  function syncLegend() {
    legendChips.forEach(({ s, c }) => c.setAttribute('aria-pressed', String(state.section === s)));
    legendEl.classList.toggle('has-active', !!state.section);
  }

  // ---------------------------------------------------------------------
  // 10. Search
  // ---------------------------------------------------------------------
  let results = [], active = 0;
  function highlight(text, q) {
    const f = document.createDocumentFragment();
    const i = text.toLowerCase().indexOf(q);
    if (i < 0) { f.append(text); return f; }
    const m = document.createElement('mark'); m.textContent = text.slice(i, i + q.length);
    f.append(text.slice(0, i), m, text.slice(i + q.length));
    return f;
  }

  function renderSuggestions() {
    const q = searchInput.value.trim().toLowerCase();
    state.query = q; applyState(); suggestions.innerHTML = '';
    if (!q) { suggestions.hidden = true; searchInput.setAttribute('aria-expanded', 'false'); return; }

    results = nodes.filter(n => matches(n))
      .sort((a, b) => (b.label.toLowerCase().startsWith(q) - a.label.toLowerCase().startsWith(q)) || a.label.localeCompare(b.label))
      .slice(0, 12);
    active = 0;

    if (!results.length) {
      const li = document.createElement('li'); li.className = 'pg-suggestion-empty'; li.textContent = 'No matching project or theme';
      suggestions.append(li);
    }
    results.forEach((n, i) => {
      const li = document.createElement('li');
      li.className = 'pg-suggestion'; li.id = `pg-opt-${i}`; li.setAttribute('role', 'option');
      li.setAttribute('aria-selected', String(i === active));
      const dot = document.createElement('span');
      dot.className = `pg-chip-dot${n.type === 'theme' ? ' is-ring' : ''}`; dot.style.setProperty('--node-color', n.color);
      const label = document.createElement('span'); label.append(highlight(n.label, q));
      const kind = document.createElement('span'); kind.className = 'pg-suggestion-kind'; kind.textContent = n.type === 'theme' ? 'theme' : n.data.year;
      li.append(dot, label, kind);
      li.addEventListener('pointerdown', e => e.preventDefault());
      li.addEventListener('click', () => choose(n));
      suggestions.append(li);
    });
    suggestions.hidden = false;
    searchInput.setAttribute('aria-expanded', 'true');
    searchInput.setAttribute('aria-activedescendant', results.length ? 'pg-opt-0' : '');
  }

  function moveActive(d) {
    if (!results.length) return;
    active = (active + d + results.length) % results.length;
    [...suggestions.children].forEach((li, i) => li.setAttribute('aria-selected', String(i === active)));
    const a = suggestions.children[active]; a.scrollIntoView({ block: 'nearest' });
    searchInput.setAttribute('aria-activedescendant', a.id);
  }
  function closeSuggestions() { suggestions.hidden = true; searchInput.setAttribute('aria-expanded', 'false'); }
  function choose(n) {
    searchInput.value = ''; state.query = ''; closeSuggestions(); searchInput.blur();
    if (n.type === 'theme' && !themesToggle.checked) { themesToggle.checked = true; applyThemeVisibility(); }
    select(n, { recenter: true });
  }

  searchInput.addEventListener('input', renderSuggestions);
  searchInput.addEventListener('focus', () => { if (searchInput.value) renderSuggestions(); });
  searchInput.addEventListener('blur', () => setTimeout(closeSuggestions, 120));
  searchInput.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); moveActive(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); moveActive(-1); }
    else if (e.key === 'Enter') { e.preventDefault(); if (results[active]) choose(results[active]); }
    else if (e.key === 'Escape') { e.stopPropagation(); searchInput.value = ''; renderSuggestions(); searchInput.blur(); }
  });

  // ---------------------------------------------------------------------
  // 11. Keyboard shortcuts & deep links
  // ---------------------------------------------------------------------
  document.addEventListener('keydown', e => {
    const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName);
    if (e.key === 'Escape') {
      if (state.selected) select(null);
      else if (state.section) { state.section = null; syncLegend(); applyState(); }
      return;
    }
    if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === '/') { e.preventDefault(); searchInput.focus(); }
    else if (e.key === 't' || e.key === 'T') { themesToggle.checked = !themesToggle.checked; applyThemeVisibility(); }
    else if (e.key === '0') { userMoved = false; fitView(true); }
    else if (e.key === '+' || e.key === '=') svg.transition().duration(ms(250)).call(zoom.scaleBy, 1.35);
    else if (e.key === '-' || e.key === '_') svg.transition().duration(ms(250)).call(zoom.scaleBy, 1 / 1.35);
  });

  function selectFromHash() {
    const m = location.hash.match(/^#node=(.+)$/);
    const n = m && byId.get(decodeURIComponent(m[1]));
    if (n) select(n, { recenter: true });
  }
  selectFromHash();
  addEventListener('hashchange', selectFromHash);
})();
